(()=>{let ctx,master,on=false;const voices=new Set();
function unlock(){try{ctx ||= new (window.AudioContext||window.webkitAudioContext)();if(!master){master=ctx.createGain();master.gain.value=on?.16:0;master.connect(ctx.destination);}if(ctx.state==='suspended')ctx.resume().catch(()=>{});}catch{}}
function setEnabled(v){on=v;if(master)master.gain.setValueAtTime(on?.16:0,ctx.currentTime);}
function tone(hz,delay=0,duration=.1,type='square',volume=.3,end=hz){if(!on||document.hidden)return;unlock();if(!ctx)return;const t=ctx.currentTime+delay,o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.frequency.setValueAtTime(hz,t);o.frequency.exponentialRampToValueAtTime(Math.max(20,end),t+duration);g.gain.setValueAtTime(.001,t);g.gain.linearRampToValueAtTime(volume,t+.008);g.gain.exponentialRampToValueAtTime(.001,t+duration);o.connect(g);g.connect(master);voices.add(o);o.onended=()=>{voices.delete(o);o.disconnect();g.disconnect();};o.start(t);o.stop(t+duration+.02);}
function play(kind){if(typeof kind==='number'){if(!kind){tone(196,0,.18,'triangle',.45,98);return;}const notes=kind===100?[523,659,784,1047,1319,1568]:kind>=85?[392,523,659,784,1047]:kind>=60?[392,494,587,784]:kind>=30?[330,440,554]:[330,440];notes.forEach((n,i)=>tone(n,i*.09,.2,'square',.22));if(kind>=85)tone(130.8,0,.65,'triangle',.4);return;}if(kind==='pitch')tone(300,0,.1,'square',.18,650);if(kind==='retry'){tone(190,0,.08,'triangle',.25);tone(150,.09,.09,'triangle',.22);}if(kind==='tick')tone(700,0,.035,'square',.12);if(kind==='start')[262,330,392].forEach((n,i)=>tone(n,i*.12,.13,'triangle',.25));if(kind==='travel'){tone(220,0,.75,'sine',.35,55);[0,.24,.48,.72].forEach(t=>tone(90,t,.05,'triangle',.2));}}
document.addEventListener('visibilitychange',()=>{if(document.hidden)for(const o of voices){try{o.stop();}catch{}}});window.DealAudio={unlock,setEnabled,play};})();